// ===== Representante comercial do bolsão =====
// O responsável de cada bolsão vem da coluna "Responsável" da lista "Matriz Bolsões" (SharePoint).
// Aqui fica só o WhatsApp de cada responsável, pelo e-mail dele (formato 55 + DDD + número).
const REPRESENTANTES = {
  'exemplo4@exemplo.com':  '5511999999999',   // Responsável A
  'exemplo5@exemplo.com': '5511999999999',   // Responsável B
};
// Recebe sempre. Também é o único destino quando o bolsão não é encontrado na Matriz.
const SEMPRE = [
  '5511999999999',          // Responsável pela automação
];
// EM TESTE: true = cada representante é trocado pelo número de teste abaixo.
// Para colocar em produção, troque para false.
const MODO_TESTE = true;
const NUMEROS_TESTE = {
  'exemplo4@exemplo.com':  '5511999999999',   // bolsões do Responsável A → Responsável pela automação
  // 5511999999999 é o próprio WhatsApp da automação: mensagem para ele mesmo não chega
  'exemplo5@exemplo.com': '5511999999999',   // bolsões da Ana → Responsável pela automação
};

const norm = s => ' ' + String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\b(rua|r|av|avenida|alameda|al|praca|travessa|estrada|bolsao)\b/g, ' ')
  .replace(/\s+/g, ' ').trim() + ' ';

// Procura o bolsão da inclusão na Matriz (ignora acentos, maiúsculas e "Rua", "Av." etc.)
const acharBolsao = (textos, matriz) => {
  for (const t of textos) {
    const alvo = norm(t);
    if (alvo.trim().length < 3) continue;
    const achados = (matriz || []).filter(b => {
      const n = norm(b.Title);
      return n.trim().length >= 3 && (alvo.includes(n) || n.includes(alvo));
    });
    if (achados.length) return achados.sort((a, b) => norm(b.Title).length - norm(a.Title).length)[0];
  }
  return null;
};

const representante = (textos, resposta) => {
  const lista = resposta && Array.isArray(resposta.value) ? resposta.value : null;
  const b = lista ? acharBolsao(textos, lista) : null;
  const resp = (b && b.Respons_x00e1_vel) || {};
  const email = String(resp.EMail || '').toLowerCase();
  const tel = MODO_TESTE ? NUMEROS_TESTE[email] : REPRESENTANTES[email];
  const anexos = (b && b.AttachmentFiles) || [];
  const kit = anexos.find(a => /\.pdf$/i.test(a.FileName)) || anexos[0] || null;
  let aviso = '';
  if (!lista) aviso = 'Não foi possível consultar a Matriz Bolsões. Mensagem enviada só para o responsável pela automação.';
  else if (!b) aviso = 'Bolsão não encontrado na Matriz Bolsões. Mensagem enviada só para o responsável pela automação.';
  else if (!tel) aviso = `Responsável "${resp.Title || 'não preenchido'}" do bolsão ${b.Title} sem WhatsApp cadastrado na automação.`;
  if (MODO_TESTE && tel) aviso = `MODO TESTE – em produção esta mensagem iria para ${resp.Title} (${REPRESENTANTES[email] || 'sem número'}).`;
  return {
    bolsaoMatriz: b ? b.Title : null,
    representante: tel ? (resp.Title || null) : null,
    // em teste vai só para o número de teste do representante; em produção, representante + SEMPRE
    numeros: MODO_TESTE ? (tel ? [tel] : SEMPRE) : (tel ? [tel] : []).concat(SEMPRE),
    aviso,
    kitNome: kit ? kit.FileName : null,
    kitCaminho: kit ? kit.ServerRelativeUrl : null,
  };
};

const valido = n => String(n).replace(/\D/g, '');
const lista = arr => [...new Set(arr.map(valido).filter(n => n.length >= 12 && n.length <= 13))].map(n => n + '@c.us');

// Mensagem do Comercial (Inclusão no Grupo): vai para o representante do bolsão
const saida = [];
$input.all().forEach((item, i) => {
  const orig = $('Preparar Mensagem Grupo').itemMatching(i).json;
  const c = $('Buscar Cliente para Mensagem').itemMatching(i).json;
  const f = c.fields || c || {};
  const r = representante([f.Title, f.LocaisInstalacao], item.json);
  lista(r.numeros).forEach(chatId => saida.push({ json: { ...orig, chatId }, pairedItem: { item: i } }));
});
return saida;

// A mesma etapa pode ter sido enviada para mais de um número (e em lembretes).
// Respondida uma delas, fecha todas, para a etapa não ser executada duas vezes.
const r = $('Organizar Resposta Comercial').first().json;
const chaves = new Set(['inclusao:comercial:poll:' + r.pollId]);
for (const [k, v] of Object.entries($json || {})) {
  try { const d = JSON.parse(v); if (String(d.itemId) === String(r.itemId) && d.etapa === r.etapa) chaves.add(k); } catch (e) {}
}
return [...chaves].map(chave => ({ json: { chave } }));
